   if(mode==='crosscheck'&&known===0&&results.length===64){const expanded=Advisor.scenarios(saved,'full').enemyPlans,shortlist=results.slice(0,3),checked=[];refinement={completed:0,total:shortlist.length,applied:false};for(const [i,row]of shortlist.entries()){const result=await evaluate(row.choices,row.itemBuilds,`Cross-check finalist ${i+1}/${shortlist.length}`,deadline,expanded);if(!result)break;checked.push(result);refinement.completed++}if(cancelled())return null;if(checked.length===shortlist.length){testPlans=expanded;ranked=checked.sort(Advisor.compare);best=ranked[0];refinement.applied=true}}
